# Meeting 2, part 5: self practice after slide 47 (Shay, 2026-11-12: the class stopped there). One full exercise with a new story,
# up to the identity table only (no column sums and no statements: those open meeting 3), with a full solution cell by cell.
# Tamar's ice cream shop, 2026: cash 86,110, customers 4,000, inventory 2,500, equipment 48,000; suppliers 32,000, accrued 1,500,
# loan 24,000; share capital 5,000, premium 45,000; revenue 110,000, expenses 76,890 (materials 9,500, wages 36,000, rent 18,000,
# electricity 1,500, interest 2,000, tax 9,890 = 23% of 43,000). Assets 140,610 = liabilities 57,500 + equity 83,110.

A4 = [('cash', 'מזומן', 'a'), ('cust', 'לקוחות', 'a'), ('inv', 'מלאי חומרי גלם', 'a'), ('ppe', 'ציוד', 'a'), ('sup', 'ספקים', 'l'), ('acc', 'הוצאות לשלם', 'l'), ('loan', 'הלוואה', 'l'),
      ('sc', 'הון מניות', 'e'), ('prem', 'פרמיה', 'e'), ('rev', 'הכנסות', 'pl'), ('exp', 'הוצאות (מינוס)', 'pl')]
TEV = ['א. ב-1.1.2026 הוקמה גלידריית תמר בע״מ. החברה הנפיקה 5,000 מניות בנות 1 ש״ח ערך נקוב כל אחת, תמורת 50,000 ש״ח במזומן.',
       'ב. החברה לוותה מהבנק 30,000 ש״ח, לפירעון בעוד ארבע שנים.',
       'ג. החברה קנתה מקפיאים, ויטרינה ומכונת גלידה ב-48,000 ש״ח. 18,000 ש״ח שולמו במזומן, והיתרה תשולם לספק בעוד שלושה חודשים.',
       'ד. החברה קנתה חלב, פירות, שוקולד וגביעים למלאי ב-12,000 ש״ח, באשראי מהספקים.',
       'ה. במהלך השנה מכרה החברה גלידה בדוכן ב-96,000 ש״ח במזומן, וסיפקה גלידה לשלוש חתונות ב-14,000 ש״ח, שבעלי האולם ישלמו בהמשך.',
       'ו. בגלידה שנמכרה נצרכו חומרי גלם שעלותם 9,500 ש״ח.',
       'ז. החברה שילמה במזומן שכר לעובדים: 36,000 ש״ח.',
       'ח. החברה שילמה במזומן שכר דירה לדוכן: 18,000 ש״ח.',
       'ט. חשבון החשמל של דצמבר, של המקפיאים, 1,500 ש״ח, ישולם רק בינואר 2027.',
       'י. בעלי האולם שילמו 10,000 ש״ח מתוך החוב שלהם.',
       'יא. החברה שילמה לספק המקפיאים 10,000 ש״ח מתוך החוב.',
       'יב. החברה העבירה לבנק 8,000 ש״ח: 6,000 ש״ח פירעון של קרן ההלוואה, ו-2,000 ש״ח ריבית.',
       'יג. החברה שילמה מס הכנסה: 9,890 ש״ח.']
TAMAR = [
 ('א. הנפקת מניות', {'cash': (50000, 'הכסף שהתקבל.'), 'sc': (5000, '5,000 מניות כפול 1 ש״ח ערך נקוב.'), 'prem': (45000, 'מה ששולם מעבר לערך הנקוב: 50,000 פחות 5,000.')}),
 ('ב. הלוואה מהבנק', {'cash': (30000, 'הכסף שהתקבל.'), 'loan': (30000, 'חוב לבנק. הלוואה אינה הכנסה: מחזירים אותה.')}),
 ('ג. ציוד, חלק באשראי', {'cash': (-18000, 'מה ששולם עכשיו.'), 'ppe': (48000, 'כל עלות הציוד, גם החלק שעוד לא שולם.'), 'sup': (30000, 'היתרה: 48,000 פחות 18,000.')}),
 ('ד. מלאי באשראי', {'inv': (12000, 'חומרי גלם במקרר: נכס, עוד לא הוצאה.'), 'sup': (12000, 'החברה חייבת לספקים.')}),
 ('ה. מכירות', {'cash': (96000, 'מה שהתקבל בדוכן.'), 'cust': (14000, 'החתונות: בעלי האולם חייבים לחברה.'), 'rev': (110000, 'כל שווי המכירות: 96,000 ועוד 14,000.')}),
 ('ו. חומרי גלם שנצרכו', {'inv': (-9500, 'חומרי הגלם יצאו מהמקרר.'), 'exp': (-9500, 'המשאב נצרך: הוצאה.')}),
 ('ז. שכר עובדים', {'cash': (-36000, 'הכסף יצא.'), 'exp': (-36000, 'הוצאת שכר.')}),
 ('ח. שכר דירה', {'cash': (-18000, 'הכסף יצא.'), 'exp': (-18000, 'הוצאת שכר דירה.')}),
 ('ט. חשמל, לא שולם', {'acc': (1500, 'חוב לחברת החשמל, ישולם בינואר.'), 'exp': (-1500, 'החשמל נצרך ב-2026, ולכן זו הוצאה של 2026.')}),
 ('י. גבייה מבעלי האולם', {'cash': (10000, 'הכסף נכנס.'), 'cust': (-10000, 'הם חייבים פחות. אין הכנסה חדשה: היא נרשמה בעסקה ה.')}),
 ('יא. תשלום לספק הציוד', {'cash': (-10000, 'הכסף יצא.'), 'sup': (-10000, 'החוב לספק קטן. אין הוצאה.')}),
 ('יב. קרן וריבית', {'cash': (-8000, 'כל מה שיצא לבנק.'), 'loan': (-6000, 'הקרן: החוב לבנק קטן. זו לא הוצאה.'), 'exp': (-2000, 'רק הריבית היא הוצאה: הוצאות מימון.')}),
 ('יג. מס הכנסה', {'cash': (-9890, 'הכסף יצא.'), 'exp': (-9890, 'מסים על ההכנסה.')})]
_chk = {}
for _lab, _e in TAMAR:
    for _k, _v in _e.items(): _chk[_k] = _chk.get(_k, 0) + _v[0]
    assert sum(v[0] for k, v in _e.items() if k in ('cash', 'cust', 'inv', 'ppe')) == sum(v[0] for k, v in _e.items() if k not in ('cash', 'cust', 'inv', 'ppe')), _lab
assert _chk == {'cash': 86110, 'cust': 4000, 'inv': 2500, 'ppe': 48000, 'sup': 32000, 'acc': 1500, 'loan': 24000, 'sc': 5000, 'prem': 45000, 'rev': 110000, 'exp': -76890}, _chk
assert round(0.23 * (110000 - 9500 - 36000 - 18000 - 1500 - 2000)) == 9890

